dec longitud : list(num) -> num;
--- longitud nil <= 0;
--- longitud (x::xs) <= 1 + longitud(xs);

(1) (defun suma (a b) (+ a b))
(2) suma a b = a + b
(3) dec suma : num # num -> num;
    --- suma(a,b) <= a + b;

(defun factorial (n)
  (if (= n 0)
      1
      (* n (factorial (- n 1)))))

dec fact : num -> num;
--- fact 0 <= 1;
--- fact n <= n * fact(n-1);
